CREATE PROCEDURE [dbo].[API_DanhSachBangCap]
(
    @Keyword NVARCHAR(100) = ''
)
AS
BEGIN
    SET NOCOUNT ON;

    SET @Keyword = ISNULL(@Keyword, '');

    SELECT
        MaBangCap,     -- Mã bằng cấp
        TenBangCap     -- Tên bằng cấp
    FROM HR_BangCapTbl
    WHERE
        @Keyword = ''
        OR MaBangCap LIKE '%' + @Keyword + '%'
        OR TenBangCap LIKE N'%' + @Keyword + '%'
    ORDER BY MaBangCap;
END

