CREATE PROCEDURE [dbo].[API_LayPhienBanQuyen]
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Ver nvarchar(50) = '';

    -- Lấy phiên bản đồng bộ từ bảng hệ thống
    SELECT @Ver = CodeValue
    FROM SY_Setup
    WHERE CodeID = 'menu_sync_ver';

    -- Trả về 1 dòng duy nhất cho Frontend đọc
    SELECT
        0 AS [code],
        'Success' AS [msg],
        @Ver AS [version];
END

CREATE PROCEDURE [dbo].[API_LuuMenu]
    @NhomNguoiDangThaoTac NVARCHAR(50) = '',
    @MenuID NVARCHAR(50),
    @OldMenuID NVARCHAR(50) = '',
    @ParentID NVARCHAR(50) = '',
    @Label NVARCHAR(250),
    @EN NVARCHAR(250) = '',
    @FormName NVARCHAR(250) = '',
    @FormKey NVARCHAR(250) = '',
    @URLPara NVARCHAR(250) = '',
    @Icon NVARCHAR(100) = '',
    @IsDisable BIT = 0,
    @IsEdit BIT = 0
AS
BEGIN
    SET NOCOUNT ON;

    -- Kiểm tra Nhóm Cha (ParentID) có hợp lệ không
    IF (@ParentID <> '')
    BEGIN
        IF NOT EXISTS (SELECT 1 FROM WA_Menu WHERE MenuID = @ParentID)
        BEGIN
            -- Tự động tạo một Menu Cha (Root) mới thay vì báo lỗi
            INSERT INTO WA_Menu (MenuID, Parent, VN, EN, FormName, FormKey, URLPara, IconClass, isDisable)
            VALUES (@ParentID, '', N'Nhóm Menu ' + @ParentID, '', '', '', '', 'folder', 0);
        END

        IF (@IsEdit = 1 AND @ParentID = @OldMenuID)
        BEGIN
            RAISERROR (N'Lỗi: Một Menu không thể tự chọn chính nó làm Nhóm Cha!', 16, 1);
            RETURN;
        END
    END

    -- Tự động bóc tách và gán tiền tố ID Nhóm Cha vào Menu ID
    IF (@IsEdit = 1)
    BEGIN
        DECLARE @OldParentID NVARCHAR(50);
        SELECT @OldParentID = ISNULL(Parent, '') FROM WA_Menu WHERE MenuID = @OldMenuID;

        -- Nếu ID hiện tại đang dính Parent cũ, cắt bỏ Parent cũ ra khỏi ID
        IF (@OldParentID <> '' AND @MenuID LIKE @OldParentID + '%')
        BEGIN
            SET @MenuID = RIGHT(@MenuID, LEN(@MenuID) - LEN(@OldParentID));
        END
    END

    -- Gắn Parent mới vào ID nếu có chọn Nhóm Cha và ID chưa chứa Nhóm Cha
    IF (@ParentID <> '' AND @MenuID NOT LIKE @ParentID + '%')
    BEGIN
        SET @MenuID = @ParentID + @MenuID;
    END

    IF (@IsEdit = 1)
    BEGIN
        -- Đổi ID nếu cần thiết
        IF (@OldMenuID <> '' AND @OldMenuID <> @MenuID)
        BEGIN
            UPDATE WA_Menu SET MenuID = @MenuID WHERE MenuID = @OldMenuID;
            UPDATE WA_UserGroupPermisstion SET MenuID = @MenuID WHERE MenuID = @OldMenuID;
            UPDATE WA_UserPermisstion SET MenuID = @MenuID WHERE MenuID = @OldMenuID;
            -- Đồng bộ cập nhật cột Parent cho các menu con nếu đổi ID của Group cha
            UPDATE WA_Menu SET Parent = @MenuID WHERE Parent = @OldMenuID;
        END

        UPDATE WA_Menu
        SET
            Parent = @ParentID,
            VN = @Label,
            EN = @EN,
            FormName = @FormName,
            FormKey = @FormKey,
            URLPara = @URLPara,
            IconClass = @Icon,
            isDisable = @IsDisable
        WHERE MenuID = @MenuID;
    END
    ELSE
    BEGIN
        IF EXISTS (SELECT 1 FROM WA_Menu WHERE MenuID = @MenuID)
        BEGIN
            RAISERROR (N'Lỗi: Menu ID này đã tồn tại trong hệ thống!', 16, 1);
            RETURN;
        END

        INSERT INTO WA_Menu (MenuID, Parent, VN, EN, FormName, FormKey, URLPara, IconClass, isDisable)
        VALUES (@MenuID, @ParentID, @Label, @EN, @FormName, @FormKey, @URLPara, @Icon, @IsDisable);
    END
END

CREATE PROCEDURE [dbo].[API_LuuQuyenCuaNhom]
    @NhomNguoiDangThaoTac NVARCHAR(50), -- BẮT BUỘC THÊM: Truyền Session Nhóm của người ĐANG BẤM NÚT LƯU
    @UserGroupID NVARCHAR(50),          -- Nhóm BỊ gán quyền
    @MenuID NVARCHAR(50),               -- Form BỊ gán quyền
    @IsRun BIT,
    @IsAdd BIT,
    @IsUpdate BIT,
    @IsDelete BIT,
    @isManager BIT,
    @isAdmin BIT,
    @isAutoLock BIT,
    @isHideAmount BIT,
    @isLockDoc BIT,
    @isUnLockDoc BIT,
    @isExportExcel BIT
AS
BEGIN
    SET NOCOUNT ON;

    -- =======================================================
    -- BƯỚC 1: CẢNH VỆ HỆ THỐNG - CHỈ SUPER ADMIN MỚI ĐƯỢC CHẠY
    -- Khoá cứng điều kiện: Mã nhóm thao tác bắt buộc phải là 'Admin'
    -- =======================================================
    IF (@NhomNguoiDangThaoTac != 'Admin')
    BEGIN
        RAISERROR (N'Lỗi Bảo Mật: Bạn không phải Giám đốc Server, cấm sửa Phân Quyền!', 16, 1);
        RETURN;
    END

    -- =======================================================
    -- BƯỚC 2: CẬP NHẬT DATABASE
    -- =======================================================
    UPDATE WA_UserGroupPermisstion
    SET
        IsRun = @IsRun,
        IsAdd = @IsAdd,
        IsUpdate = @IsUpdate,
        IsDelete = @IsDelete,
        isManager = @isManager,
        isAdmin = @isAdmin,
        isAutoLock = @isAutoLock,
        isHideAmount = @isHideAmount,
        isLockDoc = @isLockDoc,
        isUnLockDoc = @isUnLockDoc,
        isExportExcel = @isExportExcel
    WHERE UserGroupID = @UserGroupID
      AND MenuID = @MenuID;

    -- =======================================================
    -- BƯỚC 3: KÍCH HOẠT CÒI BÁO ĐỘNG CHO CÁC TRANG WEB KHÁC TỰ F5 QUYỀN
    -- =======================================================
    IF EXISTS (SELECT 1 FROM SY_Setup WHERE CodeID = 'menu_sync_ver')
        UPDATE SY_Setup SET CodeValue = CONVERT(NVARCHAR(50), GETDATE(), 126) WHERE CodeID = 'menu_sync_ver';
    ELSE
        INSERT INTO SY_Setup (CodeID, CodeName, CodeValue, GroupID) VALUES ('menu_sync_ver', N'Phiên bản đồng bộ Menu', CONVERT(NVARCHAR(50), GETDATE(), 126), 'SY');

END

CREATE PROCEDURE [dbo].[API_LuuTruongGiaoDien]
    @FormName       varchar(50)      = NULL,
    @FieldName      varchar(50)      = NULL,
    @CaptionVN      nvarchar(255)    = NULL,
    @FormatID       varchar(2)       = NULL,
    @CaptionEN      nvarchar(200)    = NULL,
    @DataSource     nvarchar(500)    = NULL,
    @IsRequired     bit              = 0,
    @FormPosition   varchar(50)      = NULL,
    @ShowInAdd      bit              = 1,
    @ShowInEdit     bit              = 1,
    @IsReadOnlyEdit bit              = 0,
    @IsReadOnlyAdd  bit              = 0,
    @ValidateRule   nvarchar(500)    = NULL,
    @DependsOn      varchar(50)      = NULL,
    @VisibleRule    nvarchar(500)    = NULL,
    @OrderNo        int              = NULL,
    @ShowInFilter   bit              = 0,
    @NoResult       bit              = 0
AS
BEGIN
    SET NOCOUNT ON;

    -- Lưu tất cả trực tiếp vào SY_FormatFields (không dùng array trong SY_FrmLstTbl nữa)
    IF EXISTS (SELECT 1 FROM SY_FormatFields WHERE FieldName = @FieldName AND FormName = @FormName)
    BEGIN
        UPDATE SY_FormatFields
        SET CaptionVN     = ISNULL(@CaptionVN,     CaptionVN),
            FormatID      = ISNULL(@FormatID,      FormatID),
            CaptionEN     = ISNULL(@CaptionEN,     CaptionEN),
            DataSource    = ISNULL(@DataSource,    DataSource),
            IsRequired    = ISNULL(@IsRequired,    IsRequired),
            FormPosition  = ISNULL(@FormPosition,  FormPosition),
            ShowInAdd     = ISNULL(@ShowInAdd,     ShowInAdd),
            ShowInEdit    = ISNULL(@ShowInEdit,    ShowInEdit),
            IsReadOnlyEdit= ISNULL(@IsReadOnlyEdit,IsReadOnlyEdit),
            IsReadOnlyAdd = ISNULL(@IsReadOnlyAdd, IsReadOnlyAdd),
            ValidateRule  = ISNULL(@ValidateRule,  ValidateRule),
            DependsOn     = ISNULL(@DependsOn,     DependsOn),
            VisibleRule   = ISNULL(@VisibleRule,   VisibleRule),
            OrderNo       = ISNULL(@OrderNo,       OrderNo),
            ShowInFilter  = ISNULL(@ShowInFilter,  ShowInFilter)
        WHERE FieldName = @FieldName AND FormName = @FormName;
    END
    ELSE
    BEGIN
        INSERT INTO SY_FormatFields
            (FormName, FieldName, CaptionVN, FormatID, CaptionEN, DataSource,
             IsRequired, FormPosition, ShowInAdd, ShowInEdit, IsReadOnlyEdit, IsReadOnlyAdd,
             ValidateRule, DependsOn, VisibleRule, OrderNo, ShowInFilter)
        VALUES
            (@FormName, @FieldName, @CaptionVN, @FormatID, @CaptionEN, @DataSource,
             @IsRequired, @FormPosition, @ShowInAdd, @ShowInEdit, @IsReadOnlyEdit, @IsReadOnlyAdd,
             @ValidateRule, @DependsOn, @VisibleRule, ISNULL(@OrderNo, 0), ISNULL(@ShowInFilter, 0));
    END

    -- Trả về dữ liệu vừa lưu
    IF @NoResult = 0
    BEGIN
        SELECT FormName, FieldName, CaptionVN, FormatID, CaptionEN, DataSource,
               IsRequired, FormPosition, ShowInAdd, ShowInEdit, IsReadOnlyEdit, IsReadOnlyAdd,
               ValidateRule, DependsOn, VisibleRule, OrderNo, ShowInFilter
        FROM SY_FormatFields
        WHERE FieldName = @FieldName AND FormName = @FormName;
    END
END

