CREATE PROCEDURE [dbo].[HR_BaoCaoNhansu2ReportStp]
@Template VARCHAR(50),
@FromDate DATETIME,
@ToDate DATETIME,
@BranchID1 NVARCHAR(MAX) = '',
@User VARCHAR(50) = ''
AS
BEGIN
SET NOCOUNT ON;

DECLARE @BranchString NVARCHAR(MAX), @SoLuongTang INT, @SoLuongGiam INT;

SELECT @BranchString = BranchID FROM SY_User WHERE UserName = @User;

DROP TABLE IF EXISTS #Person;
CREATE TABLE #Person(PersonID NVARCHAR(50) PRIMARY KEY);

INSERT INTO #Person(PersonID)
SELECT P.PersonID
FROM HR_PersonTbl P
WHERE P.PersonStatus = 4
AND (ISNULL(@BranchString,'') = '' OR EXISTS(SELECT 1 FROM STRING_SPLIT(@BranchString, ',') S WHERE LTRIM(RTRIM(S.value)) = P.BranchID));

SELECT @SoLuongTang = COUNT(*)
FROM HR_PersonTbl
WHERE NgayVaoLam >= @FromDate AND NgayVaoLam < DATEADD(DAY,1,@ToDate)
AND (@BranchID1 = '' OR BranchID IN (SELECT value FROM dbo.SY_String2TableFnc(REPLACE(@BranchID1,',',';'))));

SELECT @SoLuongGiam = COUNT(*)
FROM HR_PersonTbl
WHERE NgayNghiViec >= @FromDate AND NgayNghiViec < DATEADD(DAY,1,@ToDate) AND PersonStatus = '8'
AND (@BranchID1 = '' OR BranchID IN (SELECT value FROM dbo.SY_String2TableFnc(REPLACE(@BranchID1,',',';'))));

DROP TABLE IF EXISTS #Data;

SELECT
ROW_NUMBER() OVER(ORDER BY ISNULL(MaNVSort.SoMaNV,2147483647),P.PersonID) AS STT_Document,
P.PersonID,P.PersonName,P.ChucDanhChuyenMon,P.NgaySinh,P.TitleName,P.CMND,P.CMNDNgayCap,P.CMNDNoiCap,
N'CHI NHÁNH: '+P.BranchID AS BranchID,P.LoaiHD,HD.DanhSachHopDong,HD.NgayKyMoiNhat,HD.MucDong,
P.DiaChiThuongTru,P.SocialID,P.SocialDate,P.DienThoai,
CAST(CASE WHEN HD.NgayKyMoiNhat >= @FromDate AND HD.NgayKyMoiNhat < DATEADD(DAY,1,@ToDate) THEN 1 ELSE 0 END AS BIT) AS NhanVienMoi,
CAST(CASE WHEN EXISTS(SELECT 1 FROM HR_BaoHiemChiTietTbl CT INNER JOIN HR_BaoHiemTbl BH ON BH.DocumentID = CT.DocumentID WHERE CT.PersonID = P.PersonID) THEN 0 ELSE 1 END AS BIT) AS ThieuBaoHiem,
CAST(CASE WHEN HD.PersonID IS NULL THEN 1 ELSE 0 END AS BIT) AS ThieuHD,
@SoLuongTang AS SoLuongTang,@SoLuongGiam AS SoLuongGiam,MaNVSort.SoMaNV
INTO #Data
FROM HR_PersonView P
INNER JOIN #Person T ON T.PersonID = P.PersonID
LEFT JOIN
(
    SELECT H1.PersonID,MAX(H1.NgayKyHopDong) AS NgayKyMoiNhat,MAX(H1.MucDong) AS MucDong,
    STUFF((SELECT CHAR(13)+CHAR(10)+H2.MaHopDong FROM HR_HopDongTbl H2 WHERE H2.PersonID = H1.PersonID FOR XML PATH(''),TYPE).value('.','NVARCHAR(MAX)'),1,2,'') AS DanhSachHopDong
    FROM HR_HopDongTbl H1
    GROUP BY H1.PersonID
) HD ON P.PersonID = HD.PersonID
OUTER APPLY(SELECT PATINDEX('%[^0-9]%',REVERSE(ISNULL(P.PersonID,''))+'X')-1 AS LEN_NUM) X
OUTER APPLY(SELECT TRY_CONVERT(INT,RIGHT(ISNULL(P.PersonID,''),X.LEN_NUM)) AS SoMaNV) MaNVSort
WHERE @BranchID1 = '' OR P.BranchID IN (SELECT value FROM dbo.SY_String2TableFnc(REPLACE(@BranchID1,',',';')));

IF @Template = 'HR_BaoCaoNhanSuNVNReport'
SELECT * FROM #Data WHERE LoaiHD = 'NVN' ORDER BY ISNULL(SoMaNV,2147483647),PersonID;
ELSE IF @Template = 'HR_BaoCaoNhanSuNNNReport'
SELECT * FROM #Data WHERE LoaiHD = 'NNN' ORDER BY ISNULL(SoMaNV,2147483647),PersonID;
ELSE IF @Template = 'HR_BaoCaoNhanSuThieuHDReport'
SELECT * FROM #Data WHERE ThieuHD = 1 ORDER BY ISNULL(SoMaNV,2147483647),PersonID;
ELSE IF @Template = 'HR_BaoCaoNhanSuThieuBHReport'
SELECT * FROM #Data WHERE ThieuBaoHiem = 1 ORDER BY ISNULL(SoMaNV,2147483647),PersonID;
ELSE
SELECT * FROM #Data ORDER BY ISNULL(SoMaNV,2147483647),PersonID;

END

CREATE PROCEDURE [dbo].[HR_CaLamViec_SapCaStp]
    @SapCaID VARCHAR(30)
AS
BEGIN
    SET NOCOUNT ON;
    SET DATEFIRST 1; -- Thứ 2 = 1, Thứ 7 = 6, Chủ nhật = 7

    DECLARE
        @TuNgay DATE,
        @DenNgay DATE,

        @T2 BIT,
        @T3 BIT,
        @T4 BIT,
        @T5 BIT,
        @T6 BIT,
        @T7 BIT,
        @CN BIT,

        @ShiftIDThu2 VARCHAR(50),
        @ShiftIDThu3 VARCHAR(50),
        @ShiftIDThu4 VARCHAR(50),
        @ShiftIDThu5 VARCHAR(50),
        @ShiftIDThu6 VARCHAR(50),
        @ShiftIDThu7 VARCHAR(50),
        @ShiftIDChuNhat VARCHAR(50);

    SELECT
        @TuNgay = CAST(TuNgay AS DATE),
        @DenNgay = CAST(DenNgay AS DATE),

        @T2 = ISNULL(Thu2, 0),
        @T3 = ISNULL(Thu3, 0),
        @T4 = ISNULL(Thu4, 0),
        @T5 = ISNULL(Thu5, 0),
        @T6 = ISNULL(Thu6, 0),
        @T7 = ISNULL(Thu7, 0),
        @CN = ISNULL(ChuNhat, 0),

        @ShiftIDThu2 = ShiftIDThu2,
        @ShiftIDThu3 = ShiftIDThu3,
        @ShiftIDThu4 = ShiftIDThu4,
        @ShiftIDThu5 = ShiftIDThu5,
        @ShiftIDThu6 = ShiftIDThu6,
        @ShiftIDThu7 = ShiftIDThu7,
        @ShiftIDChuNhat = ShiftIDChuNhat
    FROM HR_SapCaTbl
    WHERE SapCaID = @SapCaID;

    IF @TuNgay IS NULL OR @DenNgay IS NULL
    BEGIN
        RAISERROR(N'Chưa có Từ ngày hoặc Đến ngày.', 16, 1);
        RETURN;
    END;

    IF NOT EXISTS (
        SELECT 1
        FROM HR_SapCaNhanVienTbl
        WHERE SapCaID = @SapCaID
    )
    BEGIN
        RAISERROR(N'Chưa có nhân viên trong tab Nhân viên.', 16, 1);
        RETURN;
    END;

    DELETE FROM HR_SapCaChiTietTbl
    WHERE SapCaID = @SapCaID;

    ;WITH DateList AS
    (
        SELECT @TuNgay AS NgayLamViec

        UNION ALL

        SELECT DATEADD(DAY, 1, NgayLamViec)
        FROM DateList
        WHERE NgayLamViec < @DenNgay
    ),
    NgayHopLe AS
    (
        SELECT
            NgayLamViec,
            DATEPART(WEEKDAY, NgayLamViec) AS ThuTrongTuan
        FROM DateList
        WHERE
            (DATEPART(WEEKDAY, NgayLamViec) = 1 AND @T2 = 1)
            OR (DATEPART(WEEKDAY, NgayLamViec) = 2 AND @T3 = 1)
            OR (DATEPART(WEEKDAY, NgayLamViec) = 3 AND @T4 = 1)
            OR (DATEPART(WEEKDAY, NgayLamViec) = 4 AND @T5 = 1)
            OR (DATEPART(WEEKDAY, NgayLamViec) = 5 AND @T6 = 1)
            OR (DATEPART(WEEKDAY, NgayLamViec) = 6 AND @T7 = 1)
            OR (DATEPART(WEEKDAY, NgayLamViec) = 7 AND @CN = 1)
    )
    INSERT INTO HR_SapCaChiTietTbl
    (
        UserAutoID,
        SapCaID,
        PersonID,
        NgayLamViec,
        TrangThaiThucTe,
        GhiChu,
        ShiftID
    )
    SELECT
        NEWID() AS UserAutoID,
        NV.SapCaID,
        NV.PersonID,
        D.NgayLamViec,

        N'Làm việc' AS TrangThaiThucTe,
        NULL AS GhiChu,

        CASE
            WHEN D.ThuTrongTuan = 1 THEN @ShiftIDThu2
            WHEN D.ThuTrongTuan = 2 THEN @ShiftIDThu3
            WHEN D.ThuTrongTuan = 3 THEN @ShiftIDThu4
            WHEN D.ThuTrongTuan = 4 THEN @ShiftIDThu5
            WHEN D.ThuTrongTuan = 5 THEN @ShiftIDThu6
            WHEN D.ThuTrongTuan = 6 THEN @ShiftIDThu7
            WHEN D.ThuTrongTuan = 7 THEN @ShiftIDChuNhat
        END AS ShiftID

    FROM HR_SapCaNhanVienTbl NV
    CROSS JOIN NgayHopLe D
    WHERE NV.SapCaID = @SapCaID

    OPTION (MAXRECURSION 1000);
END

CREATE PROCEDURE [dbo].[HR_MaNVTuTangTheoBranch]
    @BranchID NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @MaVietTat VARCHAR(20);

    SELECT TOP 1
        @MaVietTat = CASE REPLACE(UPPER(LTRIM(RTRIM(BranchID))), ' ', '')
            WHEN 'COBI'        THEN 'COBI'
            WHEN 'DONGDU'      THEN 'ĐD'
            WHEN 'ESTELLA'     THEN 'ETL'
            WHEN 'HOANGHAI'    THEN 'HH'
            WHEN 'HUNGVUONG'   THEN 'HV'
            WHEN 'NAMVINH'     THEN 'NV'
            WHEN 'SGCENTER'    THEN 'SGCT'
            WHEN 'THANHDA'     THEN 'TD'
            WHEN 'TRANHUNGDAO' THEN 'THD'
            WHEN 'VANPHONG'    THEN 'VP'
            ELSE NULL
        END
    FROM dbo.CF_BranchTbl
    WHERE BranchID = @BranchID;

    IF ISNULL(@MaVietTat, '') = ''
    BEGIN
        RAISERROR(N'Không tìm thấy mã viết tắt của chi nhánh.', 16, 1);
        RETURN;
    END;

    DECLARE @SoThuTu INT;

    SELECT
        @SoThuTu = ISNULL(
            MAX(
                TRY_CONVERT(
                    INT,
                    SUBSTRING(PersonID, LEN(@MaVietTat) + 1, LEN(PersonID))
                )
            ),
            0
        ) + 1
    FROM dbo.HR_PersonTbl
    WHERE PersonID LIKE @MaVietTat + '%'
      AND TRY_CONVERT(INT, SUBSTRING(PersonID, LEN(@MaVietTat) + 1, LEN(PersonID))) IS NOT NULL;

    SELECT
        @MaVietTat + RIGHT('000' + CONVERT(VARCHAR(10), @SoThuTu), 3) AS PersonID,
        @BranchID AS BranchID,
        @MaVietTat AS MaVietTat,
        @SoThuTu AS SoThuTu;
END

