CREATE PROCEDURE [dbo].[HR_TimeSheetCCNReportStp]
    @Ngay DATETIME=NULL,
    @PeriodID NVARCHAR(50)='',
    @BranchID NVARCHAR(MAX)='',
    @LoaiHD VARCHAR(50)='',
    @PhongBan VARCHAR(50)='',
    @PersonID1 NVARCHAR(200)='',
    @User VARCHAR(50)=''
AS
BEGIN
    SET NOCOUNT ON;

    -- Danh sách chi nhánh user được phép xem
    DROP TABLE IF EXISTS #UserAllowedBranch;
    CREATE TABLE #UserAllowedBranch
    (
        BranchID NVARCHAR(100),
        BranchName NVARCHAR(200)
    );

    INSERT INTO #UserAllowedBranch(BranchID,BranchName)
    EXEC dbo.HR_Branch_GetByUserStp @UserName=@User;

    -- Danh sách chi nhánh cuối cùng sau khi lọc quyền
    DROP TABLE IF EXISTS #FinalBranch;
    CREATE TABLE #FinalBranch
    (
        BranchID NVARCHAR(100) PRIMARY KEY
    );

    IF LTRIM(RTRIM(ISNULL(@BranchID,'')))<>''
    BEGIN
        INSERT INTO #FinalBranch(BranchID)
        SELECT DISTINCT LTRIM(RTRIM(S.value))
        FROM dbo.SY_String2TableFnc(REPLACE(@BranchID,',',';')) S
        INNER JOIN #UserAllowedBranch UA
            ON LTRIM(RTRIM(UA.BranchID))=LTRIM(RTRIM(S.value))
        WHERE LTRIM(RTRIM(ISNULL(S.value,'')))<>'';
    END
    ELSE
    BEGIN
        INSERT INTO #FinalBranch(BranchID)
        SELECT DISTINCT LTRIM(RTRIM(BranchID))
        FROM #UserAllowedBranch
        WHERE LTRIM(RTRIM(ISNULL(BranchID,'')))<>'';
    END;

    -- Chỉ process trực tiếp khi chọn đúng một chi nhánh
    IF (SELECT COUNT(*) FROM #FinalBranch)=1
    BEGIN
        DECLARE @ProcessBranch NVARCHAR(100);

        SELECT TOP 1 @ProcessBranch=BranchID
        FROM #FinalBranch;

        EXEC dbo.HR_TimeSheetDay_Process_Stp
            @Period=@PeriodID,
            @BranchID=@ProcessBranch;
    END;

    -- Hợp đồng có thể nhiều dòng, dùng APPLY tránh nhân bản chấm công
    SELECT
        T.*,
        P.*,
        HD.LoaiHD
    FROM dbo.HR_TimeSheetDayTbl T
    INNER JOIN dbo.HR_PersonTbl P
        ON P.PersonID=T.PersonID
    OUTER APPLY
    (
        SELECT TOP 1 H.LoaiHD
        FROM dbo.HR_HopDongTbl H
        WHERE H.PersonID=P.PersonID
        ORDER BY H.DateCreate DESC
    ) HD
    WHERE (@PeriodID='' OR T.PeriodID=@PeriodID)
      AND (@Ngay IS NULL OR CAST(T.Ngay AS DATE)=CAST(@Ngay AS DATE))
      AND (@PersonID1='' OR T.PersonID=@PersonID1)
      AND (@LoaiHD='' OR HD.LoaiHD=@LoaiHD)
      AND (@PhongBan='' OR P.PhongBan=@PhongBan)
      AND EXISTS
      (
          SELECT 1
          FROM #FinalBranch B
          WHERE LTRIM(RTRIM(B.BranchID))
               =LTRIM(RTRIM(P.BranchID))
      )
    ORDER BY P.BranchID,P.PhongBan,P.PersonID,T.Ngay;

    DROP TABLE IF EXISTS #FinalBranch,#UserAllowedBranch;
END;

