CREATE proc [dbo].[HR_TuDongTruPhepStp]
    @DocumentID varchar(50),
    @StatusID int,
    @PersonID varchar(50)
AS BEGIN
    SET NOCOUNT ON;

    IF @StatusID = 8
    BEGIN
        -- Lấy tổng số ngày nghỉ từ bảng chi tiết (Detail)
        DECLARE @SoNgay decimal(18,2) = (SELECT SUM(ISNULL(SoNgayNghi, 0)) FROM HR_NghiPhepDetailTbl WHERE DocumentID = @DocumentID);

        -- Lấy hình thức nghỉ (Giả sử 1 DocumentID thường có 1 loại hình thức nghỉ chính hoặc lấy dòng đầu tiên)
        DECLARE @HinhThucNghi varchar(10) = (SELECT TOP 1 HinhThucNghi FROM HR_NghiPhepDetailTbl WHERE DocumentID = @DocumentID);

        -- Lấy thông tin có lương từ danh mục
        DECLARE @CoLuong bit = (SELECT NghiCoLuong FROM HR_HinhThucNghiListTbl WHERE HinhThucNghi = @HinhThucNghi);

        -- Kiểm tra xem có file đính kèm hay không (cho trường hợp nghỉ ốm NO)
        DECLARE @HasAttach bit = 0;
        IF EXISTS (SELECT 1 FROM HR_NghiPhepAttachTbl WHERE DocumentID = @DocumentID)
            SET @HasAttach = 1;

        -- 1. Xử lý trừ phép nếu có lương
        IF @CoLuong = 1
        BEGIN
            -- Nếu là Ốm (NO) VÀ có file đính kèm -> Trừ vào phép ốm
            IF @HinhThucNghi = 'NO' AND @HasAttach = 1
            BEGIN
                IF (SELECT SoNgayPhepOm FROM HR_PersonNghiPhepTbl WHERE PersonID = @PersonID AND Nam = YEAR(GETDATE())) < @SoNgay
                BEGIN
                    RAISERROR('Không đủ ngày nghỉ ốm!', 16, 1);
                    RETURN;
                END
                UPDATE HR_PersonNghiPhepTbl SET SoNgayPhepOm = SoNgayPhepOm - @SoNgay WHERE PersonID = @PersonID AND Nam = YEAR(GETDATE());
            END
            -- Ngược lại, trừ vào phép năm (kể cả ốm mà không có file đính kèm cũng trừ phép năm)
            ELSE
            BEGIN
                IF (SELECT SoNgayConLai FROM HR_PersonNghiPhepTbl WHERE PersonID = @PersonID AND Nam = YEAR(GETDATE())) < @SoNgay
                BEGIN
                    RAISERROR('Không đủ ngày phép năm!', 16, 1);
                    RETURN;
                END
                UPDATE HR_PersonNghiPhepTbl SET SoNgayConLai = SoNgayConLai - @SoNgay, SoNgayDaSuDung = ISNULL(SoNgayDaSuDung, 0) + @SoNgay WHERE PersonID = @PersonID AND Nam = YEAR(GETDATE());
            END
        END
        -- Nếu CoLuong = 0: Không làm gì cả (Hệ thống hiểu là nghỉ không lương)
    END

    -- Cập nhật trạng thái duyệt cuối cùng
    UPDATE HR_NghiPhepTbl SET StatusID = @StatusID, NgayDuyet = GETDATE() WHERE DocumentID = @DocumentID;
END

CREATE PROCEDURE [dbo].[TinhBHStp]
(
    @PeriodID NVARCHAR(50),
    @LoaiBaoHiem NVARCHAR(50),
    @MucDong DECIMAL(18, 2)
)
AS
BEGIN
    SET NOCOUNT ON;

    -- Tỷ lệ phần trăm mặc định (theo quy định chung)
    DECLARE @BHXHNLD DECIMAL(18, 4) = 8.0;
    DECLARE @BHXHCTY DECIMAL(18, 4) = 17.5;
    DECLARE @BHYTNLD DECIMAL(18, 4) = 1.5;
    DECLARE @BHYTCTY DECIMAL(18, 4) = 3.0;
    DECLARE @BHTNNLD DECIMAL(18, 4) = 1.0;
    DECLARE @BHTNCTY DECIMAL(18, 4) = 1.0;

    -- Lấy tỉ lệ thực tế từ bảng tham số tính lương (nếu có cấu hình)
    SELECT TOP 1
        @BHXHNLD = ISNULL(BHXHNLD, 8.0),
        @BHXHCTY = ISNULL(BHXHCTY, 17.5),
        @BHYTNLD = ISNULL(BHYTNLD, 1.5),
        @BHYTCTY = ISNULL(BHYTCTY, 3.0),
        @BHTNNLD = ISNULL(BHTNNLD, 1.0),
        @BHTNCTY = ISNULL(BHTNCTY, 1.0)
    FROM dbo.HR_BangThamSoTbl
    WHERE PeriodID = @PeriodID AND LoaiBaoHiem = @LoaiBaoHiem;

    -- Trả về các mức đóng của người lao động và người sử dụng lao động
    SELECT
        CAST(ROUND(@MucDong * @BHXHNLD / 100.0, 0) AS DECIMAL(18, 2)) AS MucDongBHXHNLD,
        CAST(ROUND(@MucDong * @BHXHCTY / 100.0, 0) AS DECIMAL(18, 2)) AS MucDongBHXHNSDLD,
        CAST(ROUND(@MucDong * @BHYTNLD / 100.0, 0) AS DECIMAL(18, 2)) AS MucDongBHYTNLD,
        CAST(ROUND(@MucDong * @BHYTCTY / 100.0, 0) AS DECIMAL(18, 2)) AS MucDongBHYTNSDLD,
        CAST(ROUND(@MucDong * @BHTNNLD / 100.0, 0) AS DECIMAL(18, 2)) AS MucDongBHTNNLD,
        CAST(ROUND(@MucDong * @BHTNCTY / 100.0, 0) AS DECIMAL(18, 2)) AS MucDongBHTNNSDLD;
END

